/// Ícones do IconMCP (https://iconmcp.com) embutidos como SVG.
/// Outline (stroke 1.75, raio 2.5, 24 px) para o estado normal e solid (stroke 1.88) para o estado selecionado.
/// Renderizados como template, então `foregroundStyle` colore.
enum IconSymbol: String, CaseIterable {
    case plus
    case close
    case warning
    case database
    case serverStack
    case folder
    case table
    case view
    case key
    case link
    case dot
    case search
    case chevron
    case check
    case closeCircle
    case info
    case play
    case stop
    case clock
    case newQuery
    case newConnection
    case sidebar
    case refresh
    case sidebarLeft
    case panelBottom
    case processes
    case cloudCheck
    case cloudX
    case copy
    case alertCircle
    case trash
    case save
    case download
    case undo
    case eye
    case eyeOff

    /// Nome do ícone no IconMCP.
    var iconName: String {
        switch self {
        case .plus: "plus"
        case .close: "close"
        case .warning: "warning-triangle"
        case .database: "database"
        case .serverStack: "server"
        case .folder: "folder"
        case .table: "table"
        case .view: "rhombus"
        case .key: "key"
        case .link: "link"
        case .dot: "star-4"
        case .search: "search"
        case .chevron: "chevron-right"
        case .check: "circle-check"
        case .closeCircle: "x-circle"
        case .info: "info"
        case .play: "play"
        case .stop: "stop-circle"
        case .clock: "clock"
        case .newQuery: "database-code"
        case .newConnection: "database-plus"
        case .sidebar: "sidebar-right"
        case .refresh: "sync"
        case .sidebarLeft: "sidebar-left"
        case .panelBottom: "panel-bottom"
        case .processes: "sync"
        case .cloudCheck: "cloud-check"
        case .cloudX: "cloud-x"
        case .copy: "copy"
        case .alertCircle: "alert-circle"
        case .trash: "trash"
        case .save: "save"
        case .download: "download"
        case .undo: "undo"
        case .eye: "eye"
        case .eyeOff: "eye-off"
        }
    }

