        case .refresh: ##"<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 16 16" fill="none" stroke="#000" stroke-width="1.253" stroke-linecap="round" stroke-linejoin="round"><g><path d="M2.25 8 A5.75 5.75 0 0 1 8 2.25 C9.6 2.25 11.1 2.9 12.25 4 L13.75 5.5"/><path d="M13.75 2.25 L13.75 5.5 L10.5 5.5"/><path d="M13.75 8 A5.75 5.75 0 0 1 8 13.75 C6.4 13.75 4.9 13.1 3.75 12 L2.25 10.5"/><path d="M2.25 13.75 L2.25 10.5 L5.5 10.5"/></g></svg>"##
        }
    }

    @MainActor private static var cache: [String: NSImage] = [:]

    @MainActor func image(solid: Bool) -> NSImage {
        let key = "\(rawValue)-\(solid)"
        if let cached = Self.cache[key] { return cached }
        let img = NSImage(data: Data((solid ? solidSVG : outlineSVG).utf8)) ?? NSImage()
        img.isTemplate = true
        Self.cache[key] = img
        return img
    }
}

/// Ícone do app. `size` é o lado em pontos; `solid` troca para a versão preenchida (item selecionado).
struct Icon: View {
    let symbol: IconSymbol
    var size: CGFloat = 14
    var solid: Bool = false

    init(_ symbol: IconSymbol, size: CGFloat = 14, solid: Bool = false) {
        self.symbol = symbol
        self.size = size
        self.solid = solid
    }

    var body: some View {
        Image(nsImage: symbol.image(solid: solid))
            .renderingMode(.template)
            .resizable()
            .scaledToFit()
            .frame(width: size, height: size)
    }
}

extension DatabaseEngine {
    /// Ícone que representa o tipo de conexão em seletores e listas.
    var iconSymbol: IconSymbol {
        switch self {
        case .postgres: .database
        case .sqlServer: .serverStack
        }
    }
}
